// Synthetic complete dashboard projections frozen from Python 3.11.15.
use localbrain_core::backend::{
    db, references,
    usage::{usage_dashboard_data, UsageOptions},
};
use rusqlite::Connection;
use serde_json::{json, Value};
fn canonical(value: Value) -> Value {
    match value {
        Value::Number(n) => {
            let number = n.to_string();
            let number = if number.contains('.') {
                number.trim_end_matches('0').trim_end_matches('.')
            } else {
                &number
            };
            json!({"$number":if number=="-0"{"0"}else{number}})
        }
        Value::Array(items) => Value::Array(items.into_iter().map(canonical).collect()),
        Value::Object(items) => Value::Object(
            items
                .into_iter()
                .map(|(key, value)| (key, canonical(value)))
                .collect(),
        ),
        other => other,
    }
}
#[test]
fn complete_dashboard_matches_frozen_synthetic_cases() {
    let connection = Connection::open_in_memory().unwrap();
    connection.execute_batch(db::SCHEMA).unwrap();
    connection.execute_batch(SQL).unwrap();
    let cases: Value = serde_json::from_str(CASES).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let input = &case["options"];
        let mut options = UsageOptions::default();
        macro_rules! field {
            ($name:ident) => {
                if let Some(value) = input[stringify!($name)].as_str() {
                    options.$name = value.into();
                }
            };
        }
        field!(view);
        field!(metric);
        field!(breakdown);
        field!(source);
        field!(timezone_name);
        options.today = input["today"]
            .as_str()
            .map(|v| chrono::NaiveDate::parse_from_str(v, "%Y-%m-%d").unwrap());
        options.from_value = input["from_value"].as_str().map(str::to_owned);
        options.to_value = input["to_value"].as_str().map(str::to_owned);
        options.visible_only = input["visible_only"].as_bool().unwrap_or(false);
        let result = canonical(usage_dashboard_data(&connection, &options).unwrap());
        let hash = references::hash_payload(&result);
        assert_eq!(hash, case["hash"], "case {index} {input}: {result}");
    }
}
